// Expected: FirstName and LastName (first word is first, rest is last)
function formatRelativeName(parts: string[]) {
  if (parts.length === 0) return null;
  return {
    FirstName: parts[0],
    LastName: parts.slice(1).join(' ') || ''
  };
}

