			description: "Quantity 50 (25% discount starts)",
			price:       100.0,
			quantity:    50,
			expected:    3750.0, // 100 * 50 * 0.75
		},
	}

	fmt.Println("Running calculateDiscount tests...")
	for _, tc := range tests {
		runTest(tc)
	}
}
